#include<bits/stdc++.h>
#define LL long long
using namespace std;
LL l,n,m;
LL a[50003],maxx;
bool check(LL mid){
	int last=0,del=0;
	for(int i=1;i<=n;i++){
		if(a[i]-a[last]<mid){
			del++;
		}
		else last=i;
	}
	return del<=m;
}
int main(){
	cin>>l>>n>>m;
	for(int i=1;i<=n;i++)cin>>a[i]; 
	sort(a+1,a+1+n);
	a[++n]=l;
	LL r=l,l=1,mid;
	while(l<=r){
		mid=(l+r)/2;
		if(check(mid)){
			l=mid+1;
			maxx=mid;
		}
		else r=mid-1;
	}
	cout<<maxx;
	return 0;
}
